const knownText = query.known_text || '';
const questionedText = query.questioned_text || '';
const ngramOrder = query.ngram_order || 3;
const metric = query.metric || 'cosine';
const topK = query.top_k || 300;

if (!knownText || knownText.trim().length < 20) {
  return JSON.stringify({ error: 'known_text too short (min 20 chars)', confidence: 0 });
}
if (!questionedText || questionedText.trim().length < 20) {
  return JSON.stringify({ error: 'questioned_text too short (min 20 chars)', confidence: 0 });
}

// tokenize_char_ngrams
function tokenizeCharNgrams(text, n) {
  const normalized = text.replace(/\s+/g, ' ');
  if (n <= 0 || normalized.length < n) return [];
  const ngrams = [];
  for (let i = 0; i <= normalized.length - n; i++) {
    ngrams.push(normalized.substring(i, i + n));
  }
  return ngrams;
}

// Count n-grams
function countNgrams(text, n) {
  const tokens = tokenizeCharNgrams(text, n);
  const counts = {};
  for (const t of tokens) counts[t] = (counts[t] || 0) + 1;
  return counts;
}

// Get top-k
function getTopK(counts, k) {
  return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, k);
}

const knownCounts = countNgrams(knownText, ngramOrder);
const questionedCounts = countNgrams(questionedText, ngramOrder);
const knownTop = Object.fromEntries(getTopK(knownCounts, topK));
const questionedTop = Object.fromEntries(getTopK(questionedCounts, topK));

const vocab = [...new Set([...Object.keys(knownTop), ...Object.keys(questionedTop)])].sort();
const vecKnown = vocab.map(ng => knownTop[ng] || 0);
const vecQuest = vocab.map(ng => questionedTop[ng] || 0);

let score = 0;
if (metric === 'cosine') {
  let dot = 0, normK = 0, normQ = 0;
  for (let i = 0; i < vocab.length; i++) {
    dot += vecKnown[i] * vecQuest[i];
    normK += vecKnown[i] * vecKnown[i];
    normQ += vecQuest[i] * vecQuest[i];
  }
  if (normK && normQ) score = dot / (Math.sqrt(normK) * Math.sqrt(normQ));
} else if (metric === 'jaccard') {
  const setK = new Set(Object.keys(knownTop));
  const setQ = new Set(Object.keys(questionedTop));
  let intersection = 0;
  for (const k of setK) if (setQ.has(k)) intersection++;
  const union = new Set([...setK, ...setQ]).size;
  if (union) score = intersection / union;
}

const commonNgrams = Object.keys(knownTop).filter(k => k in questionedTop).sort();
const confidence = Math.min(1, Math.log(1 + questionedText.length) / 10);

return JSON.stringify({
  score: Math.round(score * 10000) / 10000,
  confidence: Math.round(confidence * 10000) / 10000,
  common_ngrams_count: commonNgrams.length,
  common_ngrams_sample: commonNgrams.slice(0, 15),
  known_unique_ngrams: Object.keys(knownTop).length,
  questioned_unique_ngrams: Object.keys(questionedTop).length,
  metric_used: metric,
  ngram_order: ngramOrder,
  interpretation: score > 0.85 ? 'STRONG MATCH - Very likely same author' : score > 0.65 ? 'MODERATE MATCH - Possibly same author' : score > 0.4 ? 'WEAK MATCH - Uncertain' : 'LOW MATCH - Likely different authors'
});

