const knownText = query.known_text || '';
const questionedText = query.questioned_text || '';

if (!knownText || knownText.trim().length < 20 || !questionedText || questionedText.trim().length < 20) {
  return JSON.stringify({ error: 'Both texts must be at least 20 characters', confidence: 0 });
}

// === N-gram Features ===
function tokenizeCharNgrams(text, n) {
  const normalized = text.replace(/\s+/g, ' ');
  if (n <= 0 || normalized.length < n) return [];
  const ngrams = [];
  for (let i = 0; i <= normalized.length - n; i++) ngrams.push(normalized.substring(i, i + n));
  return ngrams;
}

function countNgrams(text, n) {
  const tokens = tokenizeCharNgrams(text, n);
  const counts = {};
  for (const t of tokens) counts[t] = (counts[t] || 0) + 1;
  return counts;
}

const knownNgrams3 = countNgrams(knownText, 3);
const questionedNgrams3 = countNgrams(questionedText, 3);
const topKnown = Object.entries(knownNgrams3).sort((a, b) => b[1] - a[1]).slice(0, 10);
const topQuestioned = Object.entries(questionedNgrams3).sort((a, b) => b[1] - a[1]).slice(0, 10);
const knownKeys = new Set(topKnown.map(e => e[0]));
const questionedKeys = new Set(topQuestioned.map(e => e[0]));
const uniqueToKnown = [...knownKeys].filter(k => !questionedKeys.has(k));
const uniqueToQuestioned = [...questionedKeys].filter(k => !knownKeys.has(k));

// === Lexical Metrics (from user's ttr, rttr, hapax_ratio, yules_k) ===
function ttr(tokens) { return tokens.length > 0 ? new Set(tokens).size / tokens.length : 0; }
function rttr(tokens) { return tokens.length > 0 ? new Set(tokens).size / Math.sqrt(tokens.length) : 0; }
function hapaxRatio(tokens) {
  const counts = {};
  for (const t of tokens) counts[t] = (counts[t] || 0) + 1;
  const hapaxes = Object.values(counts).filter(c => c === 1).length;
  const types = Object.keys(counts).length;
  return types > 0 ? hapaxes / types : 0;
}
function yulesK(tokens) {
  const counts = {};
  for (const t of tokens) counts[t] = (counts[t] || 0) + 1;
  const freqSpectrum = {};
  for (const c of Object.values(counts)) freqSpectrum[c] = (freqSpectrum[c] || 0) + 1;
  const N = tokens.length;
  if (N === 0) return 0;
  let s = 0;
  for (const [i, vI] of Object.entries(freqSpectrum)) s += Math.pow(parseInt(i), 2) * vI;
  return 10000 * (s - N) / (N * N);
}

const knownTokens = knownText.toLowerCase().match(/\b[a-z']+\b/g) || [];
const questionedTokens = questionedText.toLowerCase().match(/\b[a-z']+\b/g) || [];

const knownMetrics = {
  tokens: knownTokens.length,
  types: new Set(knownTokens).size,
  ttr: Math.round(ttr(knownTokens) * 10000) / 10000,
  rttr: Math.round(rttr(knownTokens) * 10000) / 10000,
  hapax_ratio: Math.round(hapaxRatio(knownTokens) * 10000) / 10000,
  yules_k: Math.round(yulesK(knownTokens) * 100) / 100
};
const questionedMetrics = {
  tokens: questionedTokens.length,
  types: new Set(questionedTokens).size,
  ttr: Math.round(ttr(questionedTokens) * 10000) / 10000,
  rttr: Math.round(rttr(questionedTokens) * 10000) / 10000,
  hapax_ratio: Math.round(hapaxRatio(questionedTokens) * 10000) / 10000,
  yules_k: Math.round(yulesK(questionedTokens) * 100) / 100
};

// Compare metrics
const metricDifferences = {};
for (const key of ['ttr', 'rttr', 'hapax_ratio', 'yules_k']) {
  metricDifferences[key] = {
    known: knownMetrics[key],
    questioned: questionedMetrics[key],
    difference: Math.round(Math.abs(knownMetrics[key] - questionedMetrics[key]) * 10000) / 10000
  };
}

return JSON.stringify({
  ngram_features: {
    top_known_ngrams: Object.fromEntries(topKnown),
    top_questioned_ngrams: Object.fromEntries(topQuestioned),
    unique_to_known: uniqueToKnown,
    unique_to_questioned: uniqueToQuestioned,
    known_ngram_count: Object.keys(knownNgrams3).length,
    questioned_ngram_count: Object.keys(questionedNgrams3).length
  },
  lexical_metrics: {
    known_author: knownMetrics,
    questioned: questionedMetrics,
    comparison: metricDifferences
  },
  overall_assessment: {
    vocabulary_similarity: Math.round((1 - metricDifferences.ttr.difference) * 10000) / 10000,
    yules_k_similarity: knownMetrics.yules_k > 0 && questionedMetrics.yules_k > 0 ? Math.round((1 - Math.abs(knownMetrics.yules_k - questionedMetrics.yules_k) / Math.max(knownMetrics.yules_k, questionedMetrics.yules_k)) * 10000) / 10000 : 0
  }
});

