const text = query.text || '';
const comparisonText = query.comparison_text || null;

if (!text || text.trim().length < 20) {
  return JSON.stringify({ error: 'Text too short (min 20 chars)', confidence: 0 });
}

// Error pattern detection (from user's analyze_text.py - spaCy Matcher patterns)
function detectErrorPatterns(txt) {
  const errors = [];
  const lowerTxt = txt.toLowerCase();

  // Double negative: don't/cannot/can't/never + no/nothing/none/never
  const negWords = ["don't", "dont", "cannot", "can't", "cant", "never", "not"];
  const negFollow = ["no", "nothing", "none", "never"];
  for (const neg1 of negWords) {
    for (const neg2 of negFollow) {
      const pattern = new RegExp(neg1.replace("'", "['"]?") + '\\s+(?:\\w+\\s+){0,3}' + neg2, 'gi');
      const matches = txt.match(pattern);
      if (matches) {
        errors.push({ type: 'DOUBLE_NEGATIVE', instances: matches, count: matches.length });
      }
    }
  }

  // Homophone error: they're + noun
  const homophonePattern = /they'?re\s+[a-z]+ing/gi;
  const homophoneMatches = txt.match(homophonePattern);
  if (homophoneMatches) {
    errors.push({ type: 'HOMOPHONE_ERROR', instances: homophoneMatches, count: homophoneMatches.length });
  }

  // Subject-verb disagreement: he/she/it + do
  const svPattern = /\b(he|she|it)\s+do\b/gi;
  const svMatches = txt.match(svPattern);
  if (svMatches) {
    errors.push({ type: 'SUBJECT_VERB_ERROR', instances: svMatches, count: svMatches.length });
  }

  return errors;
}

// Punctuation habits
function analyzePunctuation(txt) {
  return JSON.stringify({
    commas: (txt.match(/,/g) || []).length,
    periods: (txt.match(/\./g) || []).length,
    semicolons: (txt.match(/;/g) || []).length,
    colons: (txt.match(/:/g) || []).length,
    exclamation: (txt.match(/!/g) || []).length,
    question: (txt.match(/\?/g) || []).length,
    dashes: (txt.match(/[\u2013\u2014-]/g) || []).length,
    ellipsis: (txt.match(/\.\.\./g) || []).length,
    per_1000_chars: Math.round(((txt.match(/[^\w\s]/g) || []).length / txt.length * 1000) * 10) / 10
  });
}

const errorPatterns = detectErrorPatterns(text);
const punctProfile = analyzePunctuation(text);
const totalErrors = errorPatterns.reduce((s, e) => s + e.count, 0);

const result = {
  error_patterns: errorPatterns,
  total_errors_detected: totalErrors,
  punctuation_profile: punctProfile,
  text_length: text.length,
  error_rate_per_1000: Math.round(totalErrors / text.length * 1000 * 100) / 100
};

if (comparisonText && comparisonText.trim().length >= 50) {
  const compErrors = detectErrorPatterns(comparisonText);
  const compPunct = analyzePunctuation(comparisonText);
  const compTotal = compErrors.reduce((s, e) => s + e.count, 0);

  // Compare error types
  const errorTypesA = new Set(errorPatterns.map(e => e.type));
  const errorTypesB = new Set(compErrors.map(e => e.type));
  const sharedErrors = [...errorTypesA].filter(t => errorTypesB.has(t));

  // Compare punctuation
  const punctComparison = {};
  for (const key of Object.keys(punctProfile)) {
    if (key === 'per_1000_chars') continue;
    punctComparison[key] = {
      text_a: punctProfile[key],
      text_b: compPunct[key],
      similar: Math.abs(punctProfile[key] - compPunct[key]) <= Math.max(punctProfile[key], compPunct[key]) * 0.3
    };
  }

  result.comparison = {
    error_similarity: {
      shared_error_types: sharedErrors,
      text_a_error_rate: result.error_rate_per_1000,
      text_b_error_rate: Math.round(compTotal / comparisonText.length * 1000 * 100) / 100
    },
    punctuation_comparison: punctComparison
  };
}

return result;

