const comparisonText = query.comparison_text || null;

if (!text || text.trim().length < 20) {
  return JSON.stringify({ error: 'Text too short (min 20 chars)', confidence: 0 });
}

const functionWordCategories = {
  articles: ['the', 'a', 'an'],
  prepositions: ['of', 'in', 'to', 'for', 'with', 'on', 'at', 'from', 'by', 'about', 'as', 'into', 'through', 'after', 'over', 'between', 'out', 'against', 'during', 'without', 'before', 'under', 'around', 'among'],
  pronouns: ['i', 'me', 'my', 'mine', 'myself', 'you', 'your', 'yours', 'yourself', 'he', 'him', 'his', 'himself', 'she', 'her', 'hers', 'herself', 'it', 'its', 'itself', 'we', 'us', 'our', 'ours', 'ourselves', 'they', 'them', 'their', 'theirs', 'themselves', 'this', 'that', 'these', 'those', 'who', 'whom', 'whose', 'which', 'what'],
  conjunctions: ['and', 'but', 'or', 'nor', 'for', 'yet', 'so', 'although', 'because', 'since', 'unless', 'while', 'whereas', 'whether', 'if', 'then', 'than', 'that', 'when', 'where'],
  auxiliary_verbs: ['is', 'am', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has', 'had', 'having', 'do', 'does', 'did', 'will', 'would', 'shall', 'should', 'may', 'might', 'must', 'can', 'could']
};

function analyzeWords(txt) {
  const tokens = txt.toLowerCase().match(/\b[a-z']+\b/g) || [];
  const wordCounts = {};
  for (const t of tokens) wordCounts[t] = (wordCounts[t] || 0) + 1;
  const totalWords = tokens.length;
  const functionCounts = {};
  for (const [cat, words] of Object.entries(functionWordCategories)) {
    functionCounts[cat] = words.reduce((sum, w) => sum + (wordCounts[w] || 0), 0);
  }
  const functionTotal = Object.values(functionCounts).reduce((s, v) => s + v, 0);
  const top20 = Object.entries(wordCounts).sort((a, b) => b[1] - a[1]).slice(0, 20);
  return JSON.stringify({
    total_words: totalWords,
    unique_words: Object.keys(wordCounts).length,
    top_words: Object.fromEntries(top20),
    function_word_counts: functionCounts,
    function_word_ratios: Object.fromEntries(Object.entries(functionCounts).map(([k, v]) => [k, Math.round(v / totalWords * 10000) / 10000])),
    function_word_total_ratio: Math.round(functionTotal / totalWords * 10000) / 10000
  });
}

const analysis = analyzeWords(text);

const result = {
  text_length: text.length,
  frequent_words: analysis.top_words,
  function_word_distribution: analysis.function_word_ratios,
  function_word_total_ratio: analysis.function_word_total_ratio,
  total_words: analysis.total_words,
  unique_words: analysis.unique_words
};

if (comparisonText && comparisonText.trim().length >= 50) {
  const compAnalysis = analyzeWords(comparisonText);
  // Cosine similarity on function word ratios
  const allCats = Object.keys(functionWordCategories);
  const vecA = allCats.map(c => (analysis.function_word_counts[c] || 0) / analysis.total_words);
  const vecB = allCats.map(c => (compAnalysis.function_word_counts[c] || 0) / compAnalysis.total_words);
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dot += vecA[i] * vecB[i];
    normA += vecA[i] * vecA[i];
    normB += vecB[i] * vecB[i];
  }
  const cosineSim = normA && normB ? dot / (Math.sqrt(normA) * Math.sqrt(normB)) : 0;
  const functionWordComparison = {};
  for (const cat of allCats) {
    functionWordComparison[cat] = {
      text_a_ratio: analysis.function_word_ratios[cat],
      text_b_ratio: compAnalysis.function_word_ratios[cat],
      difference: Math.round(Math.abs(analysis.function_word_ratios[cat] - compAnalysis.function_word_ratios[cat]) * 10000) / 10000
    };
  }
  result.comparison = {
    function_word_cosine_similarity: Math.round(cosineSim * 10000) / 10000,
    function_word_comparison: functionWordComparison
  };
}

return result;

