const knownText = query.known_text || '';
const questionedText = query.questioned_text || '';

if (!knownText || knownText.trim().length < 20 || !questionedText || questionedText.trim().length < 20) {
  return JSON.stringify({ error: 'Both texts must be at least 20 characters', confidence: 0 });
}

function tokenizeCharNgrams(text, n) {
  const normalized = text.replace(/\s+/g, ' ');
  if (n <= 0 || normalized.length < n) return [];
  const ngrams = [];
  for (let i = 0; i <= normalized.length - n; i++) ngrams.push(normalized.substring(i, i + n));
  return ngrams;
}

function cosineSim(a, b) {
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < Math.min(a.length, b.length); i++) {
    dot += a[i] * b[i]; normA += a[i] * a[i]; normB += b[i] * b[i];
  }
  return normA && normB ? dot / (Math.sqrt(normA) * Math.sqrt(normB)) : 0;
}

function jaccardSim(keysA, keysB) {
  const setA = new Set(keysA);
  const setB = new Set(keysB);
  let intersection = 0;
  for (const k of setA) if (setB.has(k)) intersection++;
  const union = new Set([...setA, ...setB]).size;
  return union ? intersection / union : 0;
}

const orders = [2, 3, 4, 5];
const weights = { 2: 0.2, 3: 0.3, 4: 0.3, 5: 0.2 };
const similarities = {};
let overallCosine = 0;

for (const order of orders) {
  const knownTokens = tokenizeCharNgrams(knownText, order);
  const questionedTokens = tokenizeCharNgrams(questionedText, order);
  const knownCounts = {};
  const questionedCounts = {};
  for (const t of knownTokens) knownCounts[t] = (knownCounts[t] || 0) + 1;
  for (const t of questionedTokens) questionedCounts[t] = (questionedCounts[t] || 0) + 1;
  const knownTop = Object.entries(knownCounts).sort((a, b) => b[1] - a[1]).slice(0, 300);
  const questionedTop = Object.entries(questionedCounts).sort((a, b) => b[1] - a[1]).slice(0, 300);
  const allKeys = [...new Set([...knownTop.map(e => e[0]), ...questionedTop.map(e => e[0])])].sort();
  const knownTotal = knownTop.reduce((s, e) => s + e[1], 0);
  const questionedTotal = questionedTop.reduce((s, e) => s + e[1], 0);
  const vecKnown = allKeys.map(k => (knownCounts[k] || 0) / knownTotal);
  const vecQuest = allKeys.map(k => (questionedCounts[k] || 0) / questionedTotal);
  const cos = cosineSim(vecKnown, vecQuest);
  const jac = jaccardSim(knownTop.map(e => e[0]), questionedTop.map(e => e[0]));
  similarities[`${order}-gram`] = { cosine_similarity: Math.round(cos * 10000) / 10000, jaccard_similarity: Math.round(jac * 10000) / 10000 };
  overallCosine += cos * (weights[order] || 0.25);
}

return JSON.stringify({
  multi_order_similarities: similarities,
  overall_weighted_similarity: Math.round(overallCosine * 10000) / 10000,
  interpretation: overallCosine > 0.85 ? 'STRONG MATCH across all n-gram orders' : overallCosine > 0.65 ? 'MODERATE MATCH - some stylistic similarity' : overallCosine > 0.4 ? 'WEAK MATCH - limited similarity' : 'LOW MATCH - likely different authors',
  orders_used: orders,
  weights_used: weights
});

